import random, itertools

def compute(nodes, preds):
    succ={n:[] for n in nodes}; indeg={n:len(preds[n]) for n in nodes}
    for n,ps in preds.items():
        for p in ps: succ[p].append(n)
    waves=[]; remaining=set(nodes); finish={}; path={}
    while remaining:
        ready=sorted([n for n in remaining if indeg[n]==0])
        if not ready: raise ValueError('cycle')
        waves.append(ready)
        for n in ready:
            remaining.remove(n)
            for s in succ[n]: indeg[s]-=1
            if preds[n]:
                mf=max(finish[p] for p in preds[n])
                finish[n]=nodes[n]+mf
                cands=[p for p in preds[n] if finish[p]==mf]
                path[n]=min(path[p] for p in cands)+[n]
            else:
                finish[n]=nodes[n]
                path[n]=[n]
    makespan=max(finish.values()) if finish else 0
    endpoints=[n for n in nodes if finish[n]==makespan]
    critical=min(path[n] for n in endpoints) if endpoints else []
    return waves,critical,makespan,finish,path

def brute(nodes, preds):
    # nodes: dict id->duration, preds: dict id->list preds
    # enumerate all topological orders? Better: compute finish by longest path DP in topo order
    # then enumerate all longest paths to each node and lexicographically min
    ids=list(nodes)
    # find topological order
    indeg={n:len(preds[n]) for n in nodes}; succ={n:[] for n in nodes}
    for n,ps in preds.items():
        for p in ps: succ[p].append(n)
    q=[n for n in nodes if indeg[n]==0]; topo=[]
    while q:
        n=q.pop(); topo.append(n)
        for s in succ[n]:
            indeg[s]-=1
            if indeg[s]==0: q.append(s)
    # finish
    finish={}
    for n in topo:
        if preds[n]: finish[n]=nodes[n]+max(finish[p] for p in preds[n])
        else: finish[n]=nodes[n]
    makespan=max(finish.values()) if finish else 0
    # all paths (from any source) lexicographic min per node with longest length
    # enumerate all paths via DFS memo: set of best paths per node
    paths={}
    def get(n):
        if n in paths: return paths[n]
        if not preds[n]:
            paths[n]=[[n]]; return paths[n]
        mf=max(finish[p] for p in preds[n])
        cands=[p for p in preds[n] if finish[p]==mf]
        best=None
        for p in cands:
            for pp in get(p):
                cand=pp+[n]
                if best is None or cand<best: best=cand
        paths[n]=[best]
        return paths[n]
    endpoints=[n for n in nodes if finish[n]==makespan]
    critical=min(get(n)[0] for n in endpoints) if endpoints else []
    # waves via kahn
    return critical, finish

for t in range(50000):
    n=random.randint(0,8)
    ids=[chr(ord('a')+i) for i in range(n)]
    nodes={i:random.randint(0,5) for i in ids}
    preds={i:[] for i in ids}
    # random DAG: only allow edges from lower index to higher index
    for i in range(n):
        for j in range(i+1,n):
            if random.random()<0.25:
                preds[ids[j]].append(ids[i])
    # ensure no duplicate preds
    for i in ids: preds[i]=list(dict.fromkeys(preds[i]))
    waves,critical,makespan,finish,path=compute(nodes,preds)
    bc,bf=brute(nodes,preds)
    if critical!=bc:
