import sys
from pathlib import Path

sys.setrecursionlimit(100000)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _is_nonempty_str(x):
    return isinstance(x, str) and x.strip() != ''


def _resolve(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        result = payload['result']
        if not isinstance(result, dict):
            raise ValueError('upstream component result must be an object')
        return result
    return payload


def _unwrap_subsequent(payload):
    if not isinstance(payload, dict) or set(payload.keys()) != {'name', 'result'}:
        raise ValueError('subsequent input must be an upstream component wrapper')
    result = payload['result']
    if not isinstance(result, dict):
        raise ValueError('upstream component result must be an object')
    return result


def _check_acyclic(nodes, preds):
    indeg = {n: len(preds[n]) for n in nodes}
    succ = {n: [] for n in nodes}
    for n, ps in preds.items():
        for p in ps:
            succ[p].append(n)
    queue = [n for n in nodes if indeg[n] == 0]
    count = 0
    while queue:
        n = queue.pop()
        count += 1
        for s in succ[n]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if count != len(nodes):
        raise ValueError('cycle in dependencies')


def _compute(nodes, preds):
    succ = {n: [] for n in nodes}
    indeg = {n: len(preds[n]) for n in nodes}
    for n, ps in preds.items():
        for p in ps:
            succ[p].append(n)

    waves = []
    remaining = set(nodes)
    finish = {}
    path = {}
    while remaining:
        ready = sorted([n for n in remaining if indeg[n] == 0])
        if not ready:
            raise ValueError('cycle in dependencies')
        waves.append(ready)
        for n in ready:
            remaining.remove(n)
            for s in succ[n]:
                indeg[s] -= 1
            if preds[n]:
                mf = max(finish[p] for p in preds[n])
                finish[n] = nodes[n]['duration'] + mf
                cands = [p for p in preds[n] if finish[p] == mf]
                path[n] = min(path[p] for p in cands) + [n]
            else:
                finish[n] = nodes[n]['duration']
                path[n] = [n]

    makespan = max(finish.values()) if finish else 0
    endpoints = [n for n in nodes if finish[n] == makespan]
    critical = min(path[n] for n in endpoints) if endpoints else []
    return waves, critical, makespan, finish

