import json
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def find_contracts():
    return sorted(
        p for p in ROOT.rglob('contract.json')
        if 'outputs' not in p.relative_to(ROOT).parts
    )


def main():
    out = ROOT / 'outputs'
    if out.is_symlink():
        raise ValueError('outputs must not be a symlink')
    if out.exists():
        shutil.rmtree(out)

    contracts = find_contracts()
    if not contracts:
        raise ValueError('no component contracts')

    info = {}
    for cpath in contracts:
        contract = json.loads(cpath.read_text(encoding='utf-8'))
        name = contract['name']
        info[name] = {'contract_path': cpath, 'contract': contract}

    output_to_name = {d['contract']['output']: name for name, d in info.items()}

    deps = {name: [] for name in info}
    for name, d in info.items():
        for inp in d['contract']['inputs']:
            dep = output_to_name.get(inp)
            if dep is not None and dep != name and dep not in deps[name]:
                deps[name].append(dep)

    order = []
    state = {}

    def visit(name):
        s = state.get(name, 0)
        if s == 1:
            raise ValueError('cycle in component dependencies')
        if s == 2:
            return
        state[name] = 1
        for dep in sorted(deps[name]):
            visit(dep)
        state[name] = 2
        order.append(name)

    for name in sorted(info):
        visit(name)

    for name in order:
        render_py = info[name]['contract_path'].with_name('render.py')
        subprocess.run([sys.executable, str(render_py)], cwd=ROOT, check=True)

    subprocess.run([sys.executable, str(ROOT / 'integrate.py')], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / 'final_report.py')], cwd=ROOT, check=True)


if __name__ == '__main__':
    main()

