import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _is_number(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)


def _needs_attention(result):
    if result.get('blocked') is True:
        return True
    if result.get('feasible') is False:
        return True
    if result.get('compatible') is False:
        return True
    deny = result.get('deny')
    if _is_number(deny) and deny > 0:
        return True
    score_total = result.get('score_total')
    if _is_number(score_total) and score_total >= 20:
        return True
    return False


def main():
    core_path = ROOT / 'outputs' / 'core_manifest.json'
    core_object = json.loads(core_path.read_text(encoding='utf-8'))
    if not isinstance(core_object, dict):
        raise ValueError('core manifest must be an object')
    components = core_object.get('components')
    if not isinstance(components, dict):
        raise ValueError('core manifest components must be an object')

    attention = []
    for name in sorted(components):
        result = components[name]
        if not isinstance(result, dict):
            raise ValueError('component result must be an object')
        if _needs_attention(result):
            attention.append(name)

    serialized = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(',', ':'),
        allow_nan=False,
    ).encode('utf-8')
    sha256 = hashlib.sha256(serialized).hexdigest()

    report = {
        'title': '边缘设备灰度发布',
        'component_count': len(components),
        'sha256': sha256,
        'attention': attention,
    }

    out = ROOT / 'outputs' / 'final_report.json'
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n',
        encoding='utf-8',
    )


if __name__ == '__main__':
    main()

