from transform import transform

def brute(jobs, workers):
    order=sorted(jobs,key=lambda j:j['id'])
    best=None; assign={}
    def rec(i,caps,score,cost):
        nonlocal best
        if i==len(order):
            seq=tuple(assign[j['id']] for j in order)
            cand=(score,cost,seq)
            if best is None or cand[0]>best[0] or (cand[0]==best[0] and cand[1]<best[1]) or (cand[0]==best[0] and cand[1]==best[1] and cand[2]<best[2]):
                best=cand
            return
        job=order[i]
        for wi,w in enumerate(workers):
            if job['skill'] not in w['skills']: continue
            if job['duration']>caps[wi]: continue
            nc=list(caps); nc[wi]-=job['duration']
            assign[job['id']]=w['id']
            rec(i+1,tuple(nc),score+w['affinity'].get(job['id'],0),cost+w['cost']*job['duration'])
    rec(0,tuple(w['capacity'] for w in workers),0,0)
    if best is None:
        return {'feasible':False,'score':0,'cost':0,'assignments':[]}
    S,C,seq=best
    return {'feasible':True,'score':S,'cost':C,'assignments':[{'job':j['id'],'worker':seq[k]} for k,j in enumerate(order)]}

