    contract={'name':'crew_assignment','operation':'capacity_assignment','inputs':['x'],'output':'y'}
    got=transform([{'jobs':jobs,'workers':workers}],contract)['result']
    exp=brute(jobs,workers)
    if got!=exp:
        print('MISMATCH',t,jobs,workers,got,exp); break
else:
    print('all crew random ok')
