from pathlib import Path

sys.setrecursionlimit(100000)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _is_nonempty_str(x):
    return isinstance(x, str) and x.strip() != ''


def _resolve(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        result = payload['result']
        if not isinstance(result, dict):
            raise ValueError('upstream component result must be an object')
        return result
    return payload


def _insert(ids, x):
    out = list(ids)
    bisect.insort(out, x)
    return tuple(out)


def _solve(windows, cooldown):
    wins = [w for w in windows if w['value'] >= 0]
    n = len(wins)
    if n == 0:
        return [], 0

    p = [-1] * n
    for i in range(n):
        j = i - 1
        while j >= 0 and wins[j]['end'] + cooldown > wins[i]['start']:
            j -= 1
        p[i] = j

    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        take = wins[i - 1]['value'] + (dp[p[i - 1] + 1] if p[i - 1] >= 0 else 0)
        dp[i] = max(dp[i - 1], take)

    best_value = dp[n]
    if best_value == 0:
        return [], 0

    nxt = [n] * n
    for i in range(n):
        j = i + 1
        while j < n and wins[i]['end'] + cooldown > wins[j]['start']:
            j += 1
        nxt[i] = j

    suf = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf[i] = max(suf[i + 1], wins[i]['value'] + suf[nxt[i]])

    best = None

    def dfs(i, last_end, cur, ids):
        nonlocal best
        if cur + suf[i] < best_value:
            return
        if cur > best_value:
            return
        if i == n:
            if cur == best_value:
                if best is None or ids < best:
                    best = ids
            return
        dfs(i + 1, last_end, cur, ids)
        w = wins[i]
        if w['start'] >= last_end + cooldown:
            dfs(i + 1, w['end'], cur + w['value'], _insert(ids, w['id']))

    dfs(0, float('-inf'), 0, ())
    return (list(best) if best is not None else []), best_value

